  var ALIAS = { id: 'in', nb: 'no', nn: 'no' };
  var RTL = { ar: true, fa: true };

  var asked = new URLSearchParams(location.search).get('lang');

  function known(l) {
    var base = String(l || '').toLowerCase().split(/[-_]/)[0];
    base = ALIAS[base] || base;
    return TABLE[base] ? base : null;
  }

  function pick() {
    var wanted = [];
    if (asked) { wanted.push(asked); }
    (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en'])
      .forEach(function (l) { wanted.push(l); });
    for (var i = 0; i < wanted.length; i += 1) {
      if (known(wanted[i])) { return known(wanted[i]); }
    }
    return 'en';
  }

  var lang = pick();

  // text('classCode', '4F7K') -> "Class 4F7K". A key with no translation uses English.
  function text(key) {
    var s = TABLE[lang][key] !== undefined ? TABLE[lang][key] : TABLE.en[key];
    var args = arguments;
    return String(s).replace(/\{(\d)\}/g, function (m, n) { return args[n] !== undefined ? String(args[n]) : m; });
  }

  // Sets the text of each element with data-t="<key>" under root.
  function apply(root) {
    root.querySelectorAll('[data-t]').forEach(function (el) { el.textContent = text(el.getAttribute('data-t')); });
  }

  // The language of the class. Returns true when the page must set its words again.
  function use(l) {
    var next = known(l);
    if ((asked && known(asked)) || !next || next === lang) { return false; }
    lang = next;
    document.documentElement.lang = lang;
    return true;
  }

  document.documentElement.lang = lang;
  return {
    lang: function () { return lang; },
    dir: function () { return RTL[lang] ? 'rtl' : 'ltr'; },
    text: text,
    apply: apply,
    use: use
  };
